with changed as (update public.vocabulary set difficulty_tags=difficulty_tags || '[{"framework": "krdict", "level": "beginner", "source": "韩国国立国语院《韩国语基础词典》", "confidence": 1.0, "version": "official-json-20260919"}]'::jsonb where id in ('krdict-601897-s2','krdict-601897-s3','krdict-601897-s4') and not exists(select 1 from jsonb_array_elements(difficulty_tags) t where t->>'framework'='krdict') returning id) select count(*) as changed from changed;